import groovy.json.JsonSlurper
import java.time.LocalDate
import java.time.DayOfWeek
import java.time.temporal.ChronoUnit
import java.time.format.DateTimeFormatter
import java.time.ZonedDateTime

// ================= INPUT EXTRACTION =================
def rawFdesInput = {{ n_Dugi6.outputs }}
def rawTasksInput = {{ n_P7X4Z.outputs }}
def rawAllOrgInput = {{ n_SISbB.outputs }}

if (binding.hasVariable('parameters')) {
    rawFdesInput = parameters.fdes ?: parameters.leads
    rawTasksInput = parameters.tasks ?: parameters.accounts
    if (parameters.containsKey('allOrg')) rawAllOrgInput = parameters.allOrg
}

// Extraction helper
def extractList = { rawInput ->
    if (!rawInput) return []
    def data = rawInput
    if (data instanceof String) {
        try {
            data = new JsonSlurper().parseText(data)
        } catch (Exception e) {
            return []
        }
    }
    if (data instanceof Map && data.containsKey('objects')) {
        return data.objects ?: []
    }
    if (data instanceof List) {
        return data
    }
    return []
}

def fdesInput = extractList(rawFdesInput)
def tasksInput = extractList(rawTasksInput)
def allOrgInput = extractList(rawAllOrgInput)

// Status configuration
def COMPLETED_STATUSES = ['done', 'completed']
def IN_PROGRESS_STATUSES = ['in progress', 'in-progress']

def OWNER_KEY = 'o' + 'wner'

// ================= HELPER FUNCTIONS =================

// Count working days between two dates
def countWorkingDays = { LocalDate startDate, LocalDate endDate ->
    if (startDate > endDate) return 0
    int count = 0
    LocalDate current = startDate
    while (current <= endDate) {
        DayOfWeek dow = current.getDayOfWeek()
        if (dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY) {
            count++
        }
        current = current.plusDays(1)
    }
    return count
}

// Get current week's Monday
def getCurrentWeekMonday = {
    LocalDate today = LocalDate.now()
    int dayOfWeek = today.getDayOfWeek().getValue()
    return today.minusDays(dayOfWeek - 1)
}

// Get current week's Sunday  
def getCurrentWeekSunday = {
    return getCurrentWeekMonday().plusDays(6)
}

// Parse due date from eta field (handle multiple formats including ISO with timezone)
def parseDueDate = { etaString ->
    if (!etaString) return null
    try {
        def trimmed = etaString.trim()

        // Try ISO datetime with timezone first
        try {
            def parsed = ZonedDateTime.parse(trimmed)
            return parsed.toLocalDate()
        } catch (Exception e) {
            // Not ISO format, continue to other formats
        }

        // Other date formats
        def formats = [
            DateTimeFormatter.ISO_DATE,       // 2026-08-08
            DateTimeFormatter.ofPattern("MM/dd/yyyy"),  // 1/17/2026
            DateTimeFormatter.ofPattern("M/dd/yyyy"),   // 1/17/2026 (single digit month)
            DateTimeFormatter.ofPattern("M/d/yyyy"),    // 1/7/2026 (both single digit)
            DateTimeFormatter.ofPattern("dd MMM"),
            DateTimeFormatter.ofPattern("d MMM"),
            DateTimeFormatter.ofPattern("dd/MM/yyyy"),
            DateTimeFormatter.ofPattern("yyyy-MM-dd")
        ]

        for (fmt in formats) {
            try {
                LocalDate date = LocalDate.parse(trimmed, fmt)
                // Assume current/next year for month-day format
                if (!trimmed.contains("/") && !trimmed.contains("-")) {
                    int currentYear = LocalDate.now().getYear()
                    date = date.withYear(currentYear)
                    if (date.isBefore(LocalDate.now())) {
                        date = date.withYear(currentYear + 1)
                    }
                }
                return date
            } catch (Exception e) {
                // Try next format
            }
        }
    } catch (Exception e) {
        //
    }
    return null
}

// Calculate urgency multiplier based on due date
def getUrgencyMultiplier = { LocalDate dueDate ->
    if (!dueDate) return 1.0

    long daysUntilDue = ChronoUnit.DAYS.between(LocalDate.now(), dueDate)

    if (daysUntilDue < 0) {
        return 1.25  // Overdue
    } else if (daysUntilDue <= 14) {
        return 1.0   // Due ≤14 days
    } else if (daysUntilDue <= 30) {
        return 0.5   // 15–30 days
    } else {
        return 0.2   // 30+ days
    }
}

// Calculate story points contribution for a task
// SIMPLIFIED LOGIC: ETA data isn't reliably maintained, so this drops the
// due-date spread + urgency multiplier entirely. Every task assigned to the
// owner counts at its FULL story point value, regardless of status
// (Done / In Progress / Not Started all count equally).
//
// NOTE: This changes what the metric represents — it's no longer "how loaded
// is this person THIS WEEK", it's "total story-point volume currently
// assigned to this person across all tasks in the data source". If Done
// tasks are never removed/archived from Storage 3, this number will only
// ever climb over time since completed work never ages out.
def calculateWeeklyStoryPoints = { task ->
    def props = task.properties ?: task

    def storyPointsStr = props.get('taskStoryPoints')?.toString()?.trim() ?: "0"
    double storyPoints = 0.0
    try {
        storyPoints = storyPointsStr.isDouble() ? storyPointsStr.toDouble() : 0.0
    } catch (Exception e) {
        storyPoints = 0.0
    }

    if (storyPoints <= 0) return 0.0

    // No date parsing, no spread across working days, no urgency multiplier.
    // Full story point value counts, no matter the status.
    return Math.round(storyPoints * 100) / 100.0
}

// ================= STEP 1: Map Tasks by Owner Name =================
def assigneeTasksMap = [:].withDefault { [] }

tasksInput.each { rec ->
    def props = rec.properties ?: rec
    def taskOwnerName = props.get(OWNER_KEY)?.toString()?.trim()?.toLowerCase()
    if (taskOwnerName) {
        assigneeTasksMap[taskOwnerName] << props
    }
}

// ================= STEP 2: Map Organizational Hierarchy & Metadata =================
def managerToReportsMap = [:].withDefault { [] }
def fdeNeededMap = [:]

allOrgInput.each { rec ->
    def props = rec.properties ?: rec
    def managerName = props.get('manager')?.toString()?.trim()?.toLowerCase()
    def fdeName = props.get('fde')?.toString()?.trim()
    def fdeMail = props.get('mailId')?.toString()?.trim()

    if (fdeName) {
        def fdeNeededVal = props.get('fdeNeeded')?.toString()?.trim() ?: "0"
        fdeNeededMap[fdeName.toLowerCase()] = fdeNeededVal
    }

    if (managerName && fdeName) {
        managerToReportsMap[managerName] << [
            fde: fdeName,
            mailId: fdeMail ?: ''
        ]
    }
}

// ================= STEP 3: Rank FDEs by Raw Story Point Load =================
// Fixed weekly capacity (60 pts) is dropped as the denominator — it produced
// numbers that were either near-zero or 300%+ depending on how much of the
// backlog had story points filled in. Instead, FDEs are ranked against each
// other on raw story point load (all statuses, same sum as before) and
// slotted into three bands:
//   - Top ~55% of FDEs by load  -> 70-100%
//   - Next ~27% of FDEs         -> 60-70%
//   - Bottom ~18% of FDEs       -> below 60% (floor at 35%)
// Within a band, position is still driven by each person's actual rank
// among peers, so nobody in the same band gets an identical number.
// NOTE: 'weeklyCapacity' is kept in the output for shape compatibility only —
// it is no longer used in the calculation below.

def fdeLoadList = fdesInput.collect { rec ->
    def props = rec.properties ?: rec
    def fdeName = props.fde?.toString()?.trim() ?: 'Unknown Owner'

    // Fetch tasks matching the owner's name
    def assignedTasks = assigneeTasksMap[fdeName.toLowerCase()] ?: []

    int totalTasks = assignedTasks.size()
    int completedTasks = 0
    int inProgressTasks = 0
    int pendingTasks = 0
    double storyPointsSum = 0.0
    def accountSet = [] as Set

    // 1. Extract accounts directly assigned to FDE in Node 2
    def node2Accounts = props.get('accounts') ?: props.get('account')
    if (node2Accounts instanceof List) {
        node2Accounts.each { acct ->
            def acctStr = acct?.toString()?.trim()
            if (acctStr) accountSet << acctStr
        }
    } else if (node2Accounts) {
        node2Accounts.toString().split(',').each { acct ->
            def acctStr = acct?.trim()
            if (acctStr) accountSet << acctStr
        }
    }

    // 2. Process tasks & extract accounts + sum story points (all statuses)
    assignedTasks.each { task ->
        def status = task.status?.toString()?.toLowerCase()?.trim()

        if (status in COMPLETED_STATUSES) {
            completedTasks++
        } else if (status in IN_PROGRESS_STATUSES) {
            inProgressTasks++
        } else {
            pendingTasks++
        }

        // Account extraction from tasks
        def acct = task.account?.toString()?.trim()
        if (acct) {
            accountSet << acct
        }

        storyPointsSum += calculateWeeklyStoryPoints(task)
    }

    int activeTasks = completedTasks + inProgressTasks

    // Fetch direct reports where this FDE is the manager
    def directReportsList = managerToReportsMap[fdeName.toLowerCase()] ?: []
    def reportNames = directReportsList.collect { it.fde }

    def fdeNeededVal = fdeNeededMap[fdeName.toLowerCase()] ?: props.get('fdeNeeded')?.toString()?.trim() ?: "0"

    return [
        fdeName               : fdeName,
        props                 : props,
        totalTasks            : totalTasks,
        completedTasks        : completedTasks,
        inProgressTasks       : inProgressTasks,
        pendingTasks          : pendingTasks,
        activeTasks           : activeTasks,
        storyPointsSum        : Math.round(storyPointsSum * 100) / 100.0,
        accountSet            : accountSet,
        directReportsList     : directReportsList,
        reportNames           : reportNames,
        fdeNeededVal          : fdeNeededVal,
        utilisationPercentage : 0.0,  // filled in by ranking pass below
        loadRank              : 0,    // filled in by ranking pass below
        loadBand              : ''    // filled in by ranking pass below
    ]
}

// Rank by raw story points, highest load first. toSorted() returns a new
// list but the entries are the SAME map objects as fdeLoadList, so writing
// utilisationPercentage/loadRank/loadBand below also updates fdeLoadList.
def rankedByLoad = fdeLoadList.toSorted { a, b -> b.storyPointsSum <=> a.storyPointsSum }
int n = rankedByLoad.size()

int bandACount = Math.max(1, Math.round(n * 0.55d) as int)
if (bandACount > n) bandACount = n
int bandBCount = Math.round(n * 0.27d) as int
if (bandBCount < 0) bandBCount = 0
if (bandACount + bandBCount > n) bandBCount = Math.max(0, n - bandACount)
int bandCCount = n - bandACount - bandBCount
if (bandCCount < 0) bandCCount = 0

// Linear interpolation of % within a band, based on position among band peers.
// Top of band lands near the band's upper edge, bottom near its lower edge.
def interpolate = { int posInBand, int bandSize, double high, double low ->
    if (bandSize <= 1) return high
    double frac = posInBand / (double)(bandSize - 1)
    return high - frac * (high - low)
}

rankedByLoad.eachWithIndex { item, idx ->
    double pct
    String band
    if (idx < bandACount) {
        band = 'A'
        pct = interpolate(idx, bandACount, 100.0, 70.0)
    } else if (idx < bandACount + bandBCount) {
        band = 'B'
        pct = interpolate(idx - bandACount, bandBCount, 69.9, 60.0)
    } else {
        band = 'C'
        pct = interpolate(idx - bandACount - bandBCount, bandCCount, 59.9, 35.0)
    }
    item.utilisationPercentage = Math.round(pct * 100) / 100.0
    item.loadRank = idx + 1
    item.loadBand = band
}

// Build final output preserving the ORIGINAL fdesInput order (fdeLoadList
// was never reordered — only rankedByLoad was — so this order is untouched)
def ownerUtilisationList = fdeLoadList.collect { item ->
    def props = item.props
    def resMap = [:]
    resMap.put(OWNER_KEY, item.fdeName)
    resMap.put('mailId', props.mailId ?: props.email ?: '')
    resMap.put('designation', props.designation ?: 'Unknown')
    resMap.put('manager', props.manager ?: 'Unassigned')
    resMap.put('fdeNeeded', item.fdeNeededVal)
    resMap.put('totalTasks', item.totalTasks)
    resMap.put('completedTasks', item.completedTasks)
    resMap.put('inProgressTasks', item.inProgressTasks)
    resMap.put('pendingTasks', item.pendingTasks)
    resMap.put('activeTasks', item.activeTasks)
    resMap.put('weeklyStoryPoints', item.storyPointsSum)
    resMap.put('weeklyCapacity', 60.0)
    resMap.put('utilisationPercentage', item.utilisationPercentage)
    resMap.put('utilisationFormatted', String.format("%.2f%%", item.utilisationPercentage))
    resMap.put('loadRank', item.loadRank)
    resMap.put('loadBand', item.loadBand)
    resMap.put('totalAccounts', item.accountSet.size())
    resMap.put('accountNames', item.accountSet.toList())
    resMap.put('directReportsCount', item.directReportsList.size())
    resMap.put('directReportsNames', item.reportNames)
    resMap.put('directReportsDetails', item.directReportsList)

    return resMap
}

// ================= STEP 4: Team Average (mean of individual %s) =================
double weightedAvgEfficiencyVal = 0.0
if (n > 0) {
    weightedAvgEfficiencyVal = fdeLoadList.sum { it.utilisationPercentage } / n
}
double roundedWeightedAvgEfficiency = Math.round(weightedAvgEfficiencyVal * 100) / 100.0

// ================= OUTPUT =================
return [
    result: ownerUtilisationList,
    weightedAvgEfficiency: roundedWeightedAvgEfficiency,
    weightedAvgEfficiencyFormatted: String.format("%.2f%%", roundedWeightedAvgEfficiency)
]

import groovy.json.JsonSlurper

// ===== INPUTS =====
// n_Dugi6 : FDEs reporting to the manager (db_fdse)
// n_89nCr : list of all tasks owned by those FDEs (filled inside the loop)
// n_oeRuJ : list of direct reports of each FDE (filled inside the loop)
def rawFdesInput   = {{ n_Dugi6.outputs }}
def rawTasksInput  = {{ n_89nCr.outputs }}
def rawAllOrgInput = {{ n_oeRuJ.outputs }}

def extractList = { rawInput ->
    if (rawInput == null) return []
    def data = rawInput
    if (data instanceof String) {
        def s = data.trim()
        if (!s) return []
        try { data = new JsonSlurper().parseText(s) } catch (Exception e) { return [] }
    }
    if (data instanceof Map) {
        if (data.containsKey('objects')) return (data.objects ?: []) as List
        if (data.containsKey('items'))   return (data.items ?: []) as List
        if (data.containsKey('list'))    return (data.list ?: []) as List
        return []
    }
    if (data instanceof List) return data
    return []
}

def fdesInput   = extractList(rawFdesInput)
def tasksInput  = extractList(rawTasksInput)
def allOrgInput = extractList(rawAllOrgInput)

def str = { v -> v == null ? '' : v.toString().trim() }
def propsOf = { rec -> (rec instanceof Map && rec.properties instanceof Map) ? rec.properties : (rec ?: [:]) }
def firstNonBlank = { Map p, List keys ->
    for (k in keys) { def v = str(p.get(k)); if (v) return v }
    return ''
}

final double DEFAULT_WEEKLY_CAPACITY = 60.0

def storyPointsOf = { Map t ->
    def s = str(t.get('taskStoryPoints'))
    double sp = 0.0
    try { sp = s ? s.toDouble() : 0.0 } catch (Exception e) { sp = 0.0 }
    if (sp <= 0) sp = 1.0
    return sp
}

def statusBucket = { Map t ->
    def s = str(t.get('status')).toLowerCase()
    if (s.contains('complete') || s == 'done' || s.contains('closed') || s.contains('resolved')) return 'completed'
    if (s.contains('progress')) return 'inProgress'
    if (s.contains('pending')) return 'pending'
    if (s.contains('block')) return 'blocked'
    if (s.contains('not start') || s.contains('not_start') || s.contains('todo') || s.contains('to do') || s == 'open' || s == '') return 'notStarted'
    return 'other'
}

// ---- de-duplicate tasks (same task may be fetched twice) and group by owner name + mail ----
def seenTaskIds = [] as Set
def tasksByName = [:].withDefault { [] }
def tasksByMail = [:].withDefault { [] }
tasksInput.each { rec ->
    def id = (rec instanceof Map) ? str(rec.id) : ''
    if (id && !seenTaskIds.add(id)) return
    def p = propsOf(rec)
    def n = str(p.get('owner')).toLowerCase()
    def m = str(p.get('ownerMail')).toLowerCase()
    if (n) tasksByName[n] << p
    if (m) tasksByMail[m] << p
}

// ---- direct reports: manager name -> list of FDEs ----
def reportsByManager = [:].withDefault { [] }
def seenReport = [] as Set
allOrgInput.each { rec ->
    def p = propsOf(rec)
    def mgr = firstNonBlank(p, ['Manager', 'manager']).toLowerCase()
    def fde = firstNonBlank(p, ['fde', 'name'])
    def mail = firstNonBlank(p, ['mail_id', 'mailId', 'email'])
    if (mgr && fde && seenReport.add(mgr + '|' + fde.toLowerCase())) {
        reportsByManager[mgr] << [fde: fde, mailId: mail]
    }
}

def bandFor = { double pct ->
    if (pct >= 100.0) return 'Overloaded'
    if (pct >= 70.0) return 'A'
    if (pct >= 60.0) return 'B'
    return 'C'
}

def seenFde = [] as Set
def result = []
fdesInput.each { rec ->
    def p = propsOf(rec)
    def fdeName = firstNonBlank(p, ['fde', 'name'])
    if (!fdeName) return
    def mail = firstNonBlank(p, ['mail_id', 'mailId', 'email'])
    if (!seenFde.add(fdeName.toLowerCase() + '|' + mail.toLowerCase())) return

    // tasks: match by mail first, fall back to name
    def assigned = mail ? tasksByMail[mail.toLowerCase()] : []
    if (!assigned) assigned = tasksByName[fdeName.toLowerCase()]

    int total = assigned.size()
    int completed = 0, inProgress = 0, pending = 0, notStarted = 0, blocked = 0
    double activePoints = 0.0
    def accounts = [] as LinkedHashSet

    def nodeAccounts = p.get('accounts') ?: p.get('account')
    if (nodeAccounts instanceof List) nodeAccounts.each { a -> if (str(a)) accounts << str(a) }
    else if (nodeAccounts) str(nodeAccounts).split(',').each { a -> if (a.trim()) accounts << a.trim() }

    assigned.each { t ->
        def b = statusBucket(t)
        if (b == 'completed') completed++
        else {
            if (b == 'inProgress') inProgress++
            else if (b == 'pending') pending++
            else if (b == 'blocked') blocked++
            else notStarted++
            activePoints += storyPointsOf(t)
        }
        def acct = str(t.get('account'))
        if (acct) accounts << acct
    }
    int active = total - completed

    double capacity = DEFAULT_WEEKLY_CAPACITY
    def capStr = str(p.get('weeklyCapacity'))
    if (capStr && capStr.isDouble() && capStr.toDouble() > 0) capacity = capStr.toDouble()

    double pts = Math.round(activePoints * 100) / 100.0
    double pct = capacity > 0 ? Math.round((pts / capacity) * 10000) / 100.0 : 0.0

    def reports = reportsByManager[fdeName.toLowerCase()]

    def m = [:]
    m.put('owner', fdeName)
    m.put('mailId', mail)
    m.put('designation', firstNonBlank(p, ['designation']) ?: 'Unknown')
    m.put('manager', firstNonBlank(p, ['Manager', 'manager']) ?: 'Unassigned')
    m.put('fdeNeeded', firstNonBlank(p, ['fdeNeeded']) ?: '0')
    m.put('totalTasks', total)
    m.put('completedTasks', completed)
    m.put('inProgressTasks', inProgress)
    m.put('pendingTasks', pending)
    m.put('notStartedTasks', notStarted)
    m.put('blockedTasks', blocked)
    m.put('activeTasks', active)
    m.put('weeklyStoryPoints', pts)
    m.put('weeklyCapacity', capacity)
    m.put('utilisationPercentage', (int) Math.round(pct))
    m.put('utilisationFormatted', String.format('%.2f%%', pct))
    m.put('loadBand', bandFor(pct))
    m.put('totalAccounts', accounts.size())
    m.put('accountNames', accounts.toList())
    m.put('directReportsCount', reports.size())
    m.put('directReportsNames', reports.collect { it.fde })
    m.put('directReportsDetails', reports)
    m.put('_pct', pct)
    result << m
}

double avg = result ? Math.round((result.sum { it._pct } / result.size()) * 100) / 100.0 : 0.0
result.each { it.remove('_pct') }

return [
    result: result,
    weightedAvgEfficiency: avg,
    weightedAvgEfficiencyFormatted: String.format('%.2f%%', avg)
]
